-- Test copy of the live schema (2026-10-23): tables, FKs, roles, auth.uid(), live-only helpers.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema extensions;
create extension pgcrypto schema extensions;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$
  select nullif(coalesce(current_setting('request.jwt.claim.sub', true),
                         (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')), '')::uuid
$$;
grant usage on schema auth to anon, authenticated, service_role;
grant execute on function auth.uid() to anon, authenticated, service_role;
grant usage on schema public to anon, authenticated, service_role;
-- Supabase's defaults (the lockdown migration later removed anon's).
alter default privileges for role postgres in schema public grant all on tables to authenticated, service_role;
set search_path = public, extensions;

create table public.allocations (id text not null, purchase_id text, date timestamp with time zone, supplier_name text, milk_type text, original_quantity numeric, remaining_quantity numeric, allocated_quantity numeric, destination text, destination_details jsonb, status text, average_rate numeric, details jsonb, created_at timestamp with time zone default now(), constraint allocations_pkey PRIMARY KEY (id));
create table public.app_api_keys (id text not null default ('key_'::text || (gen_random_uuid())::text), name text not null, secret_key text not null, is_active boolean not null default true, permissions jsonb not null default '{"delivery_sync": true}'::jsonb, created_at timestamp with time zone not null default now(), last_used_at timestamp with time zone, constraint app_api_keys_pkey PRIMARY KEY (id), constraint app_api_keys_secret_key_key UNIQUE (secret_key));
create table public.app_login_attempts (id bigint generated by default as identity not null, username text not null, success boolean not null default false, attempted_at timestamp with time zone not null default now(), constraint app_login_attempts_pkey PRIMARY KEY (id));
create table public.app_roles (id text not null, name text not null, description text, is_system boolean default false, permissions jsonb not null default '[]'::jsonb, created_at timestamp with time zone default now(), constraint app_roles_pkey PRIMARY KEY (id));
create table public.app_settings (id text not null, settings jsonb, general jsonb, financial jsonb, sales jsonb, inventory jsonb, expenses jsonb default '{}'::jsonb, security jsonb not null default '{}'::jsonb, constraint app_settings_pkey PRIMARY KEY (id));
create table public.app_users (id text not null, name text not null, username text not null, role_id text not null, phone text, is_active boolean default true, avatar text, last_login timestamp with time zone, created_at timestamp with time zone default now(), pin_salt text, pin_hash text, permissions jsonb not null default '[]'::jsonb, auth_user_id uuid not null default gen_random_uuid(), constraint app_users_pkey PRIMARY KEY (id), constraint app_users_username_key UNIQUE (username));
create table public.attendance (id text not null, date date, employee_id text, status text, constraint attendance_pkey PRIMARY KEY (id));
create table public.bank_transactions (id text not null, date timestamp with time zone, account_id text, type text, amount numeric default 0, details jsonb, business_day_id text, shift_session_id text, drawer_id text, cashier_id text, category text, description text, reference_id text, created_at timestamp with time zone default now(), constraint bank_transactions_pkey PRIMARY KEY (id));
create table public.business_days (id text not null, business_date date not null, status text not null default 'Open'::text, opened_at timestamp with time zone not null default now(), opened_by text, pending_at timestamp with time zone, closed_at timestamp with time zone, closed_by text, reopened_at timestamp with time zone, reopened_by text, reopen_reason text, notes text, summary jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), cash_closed_at timestamp with time zone, stock_closed_at timestamp with time zone, constraint business_days_business_date_key UNIQUE (business_date), constraint business_days_pkey PRIMARY KEY (id));
create table public.cash_drawers (id text not null, name text not null, code text not null, account_id text, location text, is_active boolean not null default true, default_float numeric(14,2) not null default 0, settings jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), constraint cash_drawers_code_key UNIQUE (code), constraint cash_drawers_pkey PRIMARY KEY (id));
create table public.cash_remittances (id text not null, business_day_id text not null, drawer_id text not null, shift_id text not null, cashier_id text not null, cashier_name text not null, declared_amount numeric(14,2) not null, counted_amount numeric(14,2), variance numeric(14,2), declared_denominations jsonb not null default '{}'::jsonb, counted_denominations jsonb not null default '{}'::jsonb, status text not null default 'Pending'::text, bag_reference text, destination_account_id text, accepted_by_user_id text, accepted_by_user_name text, declared_at timestamp with time zone not null default now(), accepted_at timestamp with time zone, resolved_at timestamp with time zone, notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), constraint cash_remittances_pkey PRIMARY KEY (id));
create table public.cash_shifts (id text not null, business_day_id text not null, business_date date not null, drawer_id text not null, user_id text not null, user_name text not null, role_name text, status text not null default 'Active'::text, opening_source text not null default 'Head Float'::text, opening_declared numeric(14,2) not null default 0, opening_counted numeric(14,2) not null default 0, opening_variance numeric(14,2) not null default 0, opening_denominations jsonb not null default '{}'::jsonb, started_at timestamp with time zone not null default now(), closing_started_at timestamp with time zone, closed_at timestamp with time zone, closed_by text, gross_sales numeric(14,2) not null default 0, cash_sales numeric(14,2) not null default 0, online_sales numeric(14,2) not null default 0, credit_sales numeric(14,2) not null default 0, cash_collections numeric(14,2) not null default 0, cash_refunds numeric(14,2) not null default 0, cash_expenses numeric(14,2) not null default 0, cash_purchases numeric(14,2) not null default 0, other_cash_in numeric(14,2) not null default 0, other_cash_out numeric(14,2) not null default 0, bills_count integer not null default 0, expected_closing_cash numeric(14,2), closing_counted_cash numeric(14,2), closing_variance numeric(14,2), closing_denominations jsonb not null default '{}'::jsonb, leave_in_drawer numeric(14,2) not null default 0, remit_to_head numeric(14,2) not null default 0, difference_reason text, notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), constraint cash_shifts_pkey PRIMARY KEY (id));
create table public.cash_variances (id text not null, business_day_id text not null, shift_id text, handover_id text, remittance_id text, variance_type text not null, expected_amount numeric(14,2) not null, counted_amount numeric(14,2) not null, variance numeric(14,2) not null, reason text, status text not null default 'Open'::text, reported_by text, resolved_by text, resolved_at timestamp with time zone, resolution_notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), constraint cash_variances_pkey PRIMARY KEY (id));
create table public.customer_orders (id text not null, order_number text not null, customer_id text not null, customer_name text not null, customer_phone text not null default ''::text, fulfillment text not null, due_date date not null, due_time text not null default ''::text, address text not null default ''::text, notes text not null default ''::text, items jsonb not null, subtotal numeric(14,2) not null, discount numeric(14,2) not null default 0, total numeric(14,2) not null, status text not null default 'Pending'::text, revision integer not null default 1, sale_id text, created_by text not null, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), history jsonb not null default '[]'::jsonb, advance_paid numeric not null default 0, payment_mode text not null default 'Unpaid'::text, payment_status text not null default 'Unpaid'::text, payment_notes text not null default ''::text, advance_posted numeric(14,2) not null default 0, constraint customer_orders_order_number_key UNIQUE (order_number), constraint customer_orders_pkey PRIMARY KEY (id), constraint customer_orders_sale_id_key UNIQUE (sale_id));
create table public.customer_transactions (id text not null, customer_id text, date timestamp with time zone, type text, amount numeric default 0, details jsonb, business_day_id text, shift_session_id text, drawer_id text, cashier_id text, created_at timestamp with time zone default now(), constraint customer_transactions_pkey PRIMARY KEY (id));
