create table public.daily_supply (id text not null, date timestamp with time zone, customer_id text, total_amount numeric default 0, details jsonb, business_day_id text, shift_session_id text, drawer_id text, cashier_id text, constraint daily_supply_pkey PRIMARY KEY (id));
