create table public.expense_vendor_transactions (id text not null, vendor_id text, date timestamp with time zone, type text, amount numeric default 0, details jsonb default '{}'::jsonb, created_at timestamp with time zone default now(), constraint expense_vendor_transactions_pkey PRIMARY KEY (id));
create table public.expense_vendors (id text not null, name text, details jsonb, constraint expense_vendors_pkey PRIMARY KEY (id));
create table public.expenses (id text not null, date timestamp with time zone, category text, amount numeric default 0, description text, details jsonb, business_day_id text, shift_session_id text, drawer_id text, cashier_id text, created_at timestamp with time zone default now(), constraint expenses_pkey PRIMARY KEY (id));
