create table public.items (id text not null, name text not null, category text, type text[], stock numeric default 0, cost_price numeric default 0, selling_price numeric default 0, unit text, is_active boolean default true, is_system boolean default false, recipe jsonb default '[]'::jsonb, variants jsonb default '[]'::jsonb, recipe_base_item_id text, recipe_base_quantity numeric, recipe_expected_output numeric, unit_group_id text, variant_stocks jsonb default '{}'::jsonb, reorder_level numeric default 10, description text, source text default 'Both'::text, quick_amounts jsonb default '[]'::jsonb, allow_loose_sale boolean default true, image_url text, sort_order integer default 999, pos_primary_mode text default 'amount'::text, constraint items_pkey PRIMARY KEY (id));
