create table public.supplier_transactions (id text not null, supplier_id text, date timestamp with time zone, type text, amount numeric default 0, details jsonb, created_at timestamp with time zone default now(), constraint supplier_transactions_pkey PRIMARY KEY (id));
create table public.suppliers (id text not null, name text not null, phone text, balance numeric default 0, is_active boolean default true, data jsonb, constraint suppliers_pkey PRIMARY KEY (id));

alter table sales add constraint sales_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT;
alter table purchases add constraint purchases_supplier_id_fkey FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE;
alter table material_purchases add constraint material_purchases_supplier_id_fkey FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE;
alter table daily_supply add constraint daily_supply_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;
alter table attendance add constraint attendance_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES employees(id);
alter table employee_transactions add constraint employee_transactions_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES employees(id);
alter table bank_transactions add constraint bank_transactions_account_id_fkey FOREIGN KEY (account_id) REFERENCES financial_accounts(id);
alter table customer_transactions add constraint customer_transactions_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT;
alter table supplier_transactions add constraint supplier_transactions_supplier_id_fkey FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE;
alter table app_users add constraint app_users_role_id_fkey FOREIGN KEY (role_id) REFERENCES app_roles(id) ON DELETE RESTRICT;
alter table cash_shifts add constraint cash_shifts_business_day_id_fkey FOREIGN KEY (business_day_id) REFERENCES business_days(id);
alter table cash_shifts add constraint cash_shifts_drawer_id_fkey FOREIGN KEY (drawer_id) REFERENCES cash_drawers(id);
alter table drawer_handovers add constraint drawer_handovers_from_shift_id_fkey FOREIGN KEY (from_shift_id) REFERENCES cash_shifts(id);
alter table drawer_handovers add constraint drawer_handovers_to_shift_id_fkey FOREIGN KEY (to_shift_id) REFERENCES cash_shifts(id);
alter table cash_remittances add constraint cash_remittances_shift_id_fkey FOREIGN KEY (shift_id) REFERENCES cash_shifts(id);
alter table cash_variances add constraint cash_variances_shift_id_fkey FOREIGN KEY (shift_id) REFERENCES cash_shifts(id);
alter table shift_cash_events add constraint shift_cash_events_drawer_id_fkey FOREIGN KEY (drawer_id) REFERENCES cash_drawers(id);
alter table expense_vendor_transactions add constraint expense_vendor_transactions_vendor_id_fkey FOREIGN KEY (vendor_id) REFERENCES expense_vendors(id) ON DELETE CASCADE;
alter table customer_orders add constraint customer_orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id);
alter table customer_orders add constraint customer_orders_sale_id_fkey FOREIGN KEY (sale_id) REFERENCES sales(id);

grant select, insert, update, delete, truncate, references, trigger, maintain on all tables in schema public to authenticated, service_role;
grant usage on all sequences in schema public to authenticated;

-- Live-only helpers (bodies copied from pg_get_functiondef on 2026-10-23).
create function public.adjust_account_balance(p_account_id text, p_delta numeric) returns numeric language sql security definer set search_path to 'public' as $function$
  update financial_accounts set balance = round(balance + p_delta, 2) where id = p_account_id returning balance;
$function$;
create function public.adjust_customer_balance(p_customer_id text, p_delta numeric) returns numeric language sql security definer set search_path to 'public' as $function$
  update customers set balance = round(balance + p_delta, 2) where id = p_customer_id returning balance;
$function$;
create function public.adjust_supplier_balance(p_supplier_id text, p_delta numeric) returns numeric language sql security definer set search_path to 'public' as $function$
  update suppliers set balance = round(balance + p_delta, 2) where id = p_supplier_id returning balance;
$function$;
create function public.mooco_set_updated_at() returns trigger language plpgsql set search_path to '' as $function$
begin new.updated_at := now(); return new; end;
$function$;
create function public.sync_cash_drawer_from_account() returns trigger language plpgsql set search_path to 'public' as $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    UPDATE public.cash_drawers SET is_active = false, updated_at = now() WHERE id = OLD.id;
    RETURN OLD;
  ELSIF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    IF NEW.type = 'Cash' THEN
      INSERT INTO public.cash_drawers (id, name, code, account_id, is_active, default_float, settings, created_at, updated_at)
      VALUES (NEW.id, NEW.name, COALESCE(NULLIF(UPPER(LEFT(REGEXP_REPLACE(NEW.name, '[^a-zA-Z0-9]', '', 'g'), 6)), ''), 'CASH'), NEW.id, COALESCE(NEW.is_active, true), 0, '{}'::jsonb, now(), now())
      ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, account_id = EXCLUDED.account_id, is_active = EXCLUDED.is_active, updated_at = now();
    ELSE
      UPDATE public.cash_drawers SET is_active = false, updated_at = now() WHERE id = NEW.id;
    END IF;
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$function$;
create trigger trg_sync_cash_drawer_from_account after insert or delete or update on public.financial_accounts for each row execute function public.sync_cash_drawer_from_account();
create function public.record_customer_payment_effects(p_tx_id text, p_customer_id text, p_amount numeric, p_date text, p_type text, p_details jsonb DEFAULT '{}'::jsonb, p_account_id text DEFAULT NULL::text, p_business_day_id text DEFAULT NULL::text, p_shift_session_id text DEFAULT NULL::text, p_drawer_id text DEFAULT NULL::text, p_cashier_id text DEFAULT NULL::text)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare
  v_amount numeric := round(p_amount, 2);
  v_delta numeric;
  v_btx_id text := 'btx_' || p_tx_id;
begin
  if p_tx_id is null or p_tx_id = '' then raise exception 'tx_id zaroori hai.'; end if;
  if v_amount is null or v_amount <= 0 then raise exception 'Amount 0 se bara hona chahiye.'; end if;
  if p_type not in ('Payment', 'Charge') then raise exception 'Type Payment ya Charge hona chahiye.'; end if;
  if exists (select 1 from customer_transactions where id = p_tx_id) then
    return jsonb_build_object('already_applied', true, 'tx_id', p_tx_id);
  end if;
  v_delta := case when p_type = 'Payment' then -v_amount else v_amount end;
  insert into customer_transactions (id, customer_id, date, type, amount, details, business_day_id, shift_session_id, drawer_id, cashier_id)
  values (p_tx_id, p_customer_id, p_date::timestamptz, p_type, v_amount,
     p_details || jsonb_build_object('business_day_id', p_business_day_id, 'shift_session_id', p_shift_session_id, 'drawer_id', p_drawer_id, 'cashier_id', p_cashier_id),
     p_business_day_id, p_shift_session_id, p_drawer_id, p_cashier_id);
  perform public.adjust_customer_balance(p_customer_id, v_delta);
  if p_type = 'Payment' and p_account_id is not null then
    insert into bank_transactions (id, account_id, amount, date, type, category, description, reference_id, business_day_id, shift_session_id, drawer_id, cashier_id)
    values (v_btx_id, p_account_id, v_amount, p_date::timestamptz, 'Income', 'Customer Receipt', coalesce(p_details ->> 'description', 'Customer Receipt'), p_tx_id, p_business_day_id, p_shift_session_id, p_drawer_id, p_cashier_id);
    perform public.adjust_account_balance(p_account_id, v_amount);
  end if;
  return jsonb_build_object('applied', true, 'tx_id', p_tx_id);
end;
$function$;
